import{_ as e,o as s,c as n,a6 as r}from"./chunks/framework.CCKCzdWs.js";const o="/screenshots/jetbrains-failures.png",p=JSON.parse('{"title":"JetBrains plugin","description":"The Piwi plugin for WebStorm, IntelliJ IDEA Ultimate, Rider and the other JetBrains IDEs with the LSP API: what it needs, and where it shows the failures, the lines above the code, the status bar and the recording controls.","frontmatter":{"title":"JetBrains plugin","description":"The Piwi plugin for WebStorm, IntelliJ IDEA Ultimate, Rider and the other JetBrains IDEs with the LSP API: what it needs, and where it shows the failures, the lines above the code, the status bar and the recording controls.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/jetbrains.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/jetbrains.html"}],["meta",{"property":"og:title","content":"JetBrains plugin | Piwi Dashboard"}],["meta",{"property":"og:description","content":"The Piwi plugin for WebStorm, IntelliJ IDEA Ultimate, Rider and the other JetBrains IDEs with the LSP API: what it needs, and where it shows the failures, the lines above the code, the status bar and the recording controls."}]]},"headers":[],"relativePath":"features/jetbrains.md","filePath":"features/jetbrains.md","lastUpdated":1793300082000}'),i={name:"features/jetbrains.md"};function a(h,t,l,d,g,c){return s(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="jetbrains-plugin" tabindex="-1">JetBrains plugin <a class="header-anchor" href="#jetbrains-plugin" aria-label="Permalink to &quot;JetBrains plugin&quot;">​</a></h1><p>The Piwi plugin brings the <a href="./editors.html">editor extensions</a> to the JetBrains IDEs with the LSP API: WebStorm, IntelliJ IDEA Ultimate, Rider and the others, from 2024.1. It runs the same editor service as the VS Code extension, so the editor pages describe it too, with the JetBrains names of each action. This page lists what the plugin needs, and where it shows what VS Code shows differently.</p><figure><img src="'+o+'" alt="WebStorm: the failing tests tinted in the spec, the Piwi tool window below with the run&#39;s failures"><figcaption>WebStorm: the latest run&#39;s failures in the Piwi tool window, a local run laid over them, the failing tests tinted above.</figcaption></figure><h2 id="install-and-start" tabindex="-1">Install and start <a class="header-anchor" href="#install-and-start" aria-label="Permalink to &quot;Install and start&quot;">​</a></h2><p>Install <strong>Piwi</strong> from <strong>Settings → Plugins</strong> or the <strong><a href="https://plugins.jetbrains.com/plugin/34674-piwi" target="_blank" rel="noreferrer">JetBrains Marketplace ↗</a></strong>. IntelliJ IDEA Community Edition and Android Studio lack the LSP API the plugin needs.</p><p>The plugin starts the editor service with the project&#39;s Node.js interpreter, 20 or later (<strong>Settings → Languages &amp; Frameworks → Node.js</strong>, which the status bar opens when it is missing or older), once it finds a Playwright config within four folders of the project&#39;s (in Rider, the solution&#39;s) or of its Git root, and looks again on <strong>Tools → Piwi → Refresh</strong>. It reads the connection the reporter already uses; otherwise, <strong>Settings → Tools → Piwi</strong> signs you in with the browser: <a href="./editor-connection.html">Editor connection</a>.</p><p>The first trusted project with a Playwright config that nothing connects yet shows one notification, once per installation, with <strong>Connect…</strong>, <strong>Open the Failures</strong> and <strong>Learn More</strong>.</p><h2 id="where-things-are" tabindex="-1">Where things are <a class="header-anchor" href="#where-things-are" aria-label="Permalink to &quot;Where things are&quot;">​</a></h2><p>The IDE&#39;s LSP client shows warnings, quick fixes (Alt+Enter) and hover in open files; the rest is native, and every action is under <strong>Tools → Piwi</strong>:</p><ul><li><strong>The Piwi tool window</strong> names the connection and holds the <a href="./editor-failures.html#the-failures-view">failures view</a>, since the IDE highlights open files only.</li><li><strong>Code Vision</strong> shows the lines above files, locators and failing lines; each test&#39;s result is in the gutter, and a click on its icon opens the test in the dashboard.</li><li><strong>The status bar</strong> shows the latest run, or the run in progress, of the selected file&#39;s Playwright config, with an icon for its state and the error color while its tests fail; a click opens a menu of the actions, led by what the item calls for: <a href="./editor-runs.html#the-status-bar">the status bar</a>.</li><li><strong>The editor&#39;s context menu</strong> of a spec holds <strong>Run the Test at the Caret</strong>, <strong>Verify the Test at the Caret ×3</strong> and <strong>Run This Spec</strong>.</li><li><strong><a href="./editor-recording.html">Recording</a></strong> starts from <strong>Record Here</strong>, Alt+Enter or Alt+Insert, and <strong>File → New → Record a New Test File…</strong>; its controls are in a banner above the editor.</li><li><strong><a href="./editor-run-control.html">A paused run</a></strong>: the line a run Piwi started is stopped at has an arrow in the gutter and an inlay above it with <strong>Resume</strong>, <strong>Step</strong>, <strong>Run to Caret</strong>, <strong>Finish</strong> and <strong>End Test</strong>; they are also first in the status bar item&#39;s menu and under <strong>Tools → Piwi</strong>, with <strong>Pause the Run</strong> and <strong>Stop the Run</strong>. A headless test&#39;s page shows in the Piwi tool window&#39;s <strong>Paused Page</strong> tab, where a click on the image picks the locator of the element under it. On a JetBrains Gateway backend, forward the ports <strong>Pair with Piwi Picker</strong> names: <a href="/guide/remote-development.html#jetbrains-gateway">Remote development</a>.</li><li><strong><a href="./editor-stop-code.html">Code from a pause</a></strong>: the inlay, the arrow&#39;s menu, the status bar item&#39;s menu and <strong>Tools → Piwi</strong> also offer <strong>Pick a Locator</strong>, <strong>Record Here</strong>, <strong>Assert</strong>, <strong>Assert a Region</strong> and <strong>Mock a Request</strong> (the inlay names them shorter), whose code goes above the stopped line in one undoable edit; the end of the caret&#39;s line says how many elements its locator matches on the stopped page, and a failure held there reads <code>Failed · …</code>.</li><li><strong>The severity of a failure</strong>: <strong>Settings → Tools → Piwi → Runs</strong> chooses it (<a href="./editor-failures.html#ci-failures-in-the-problems-panel">CI failures in the Problems panel</a>); an information shows as a weak warning.</li><li><strong>Piwi&#39;s MCP server for the agent</strong>: <strong>Settings → Tools → Piwi → AI Assistant</strong> chooses whether the copied configuration holds the IDE&#39;s key or has the agent sign in through the browser (<a href="./editors.html#piwi-s-mcp-server-for-the-agent">Piwi&#39;s MCP server for the agent</a>).</li><li><strong><a href="./agent-run-control.html">Run control for agents</a></strong>: <strong>Tools → Piwi → Copy the Runs&#39; MCP Server Configuration for Agents</strong> gives the AI Assistant or another agent the test runs the project starts, to follow, stop and act on, and <strong>…for Claude Code or Cursor</strong> the HTTP entry they read; <strong>Reset the Runs&#39; MCP Server Token</strong> gives it a new token; <strong>Settings → Tools → Piwi → AI Assistant</strong> turns it off. A stop&#39;s menu and <strong>Tools → Piwi</strong> offer <strong>Share the Stopped Browser with Playwright Tools</strong>, after a warning.</li><li><strong><a href="./ide-integration.html#jetbrains-ides-the-piwi-plugin">Open in IDE</a></strong>: a path clicked in the dashboard or the desktop app opens at its line, with nothing to set up.</li></ul><p>The shortcuts are those of VS Code (<a href="./editors.html#commands">Commands</a>), but a run&#39;s controls, which use the debugger&#39;s shortcuts of your keymap while they apply: in the default keymap <code>F9</code> pauses and resumes, <code>F8</code> steps, <code>Alt+F9</code> runs to the caret and <code>Shift+F8</code> finishes. <strong>Settings → Keymap</strong> changes them (search <code>Piwi</code>).</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./editors.html">Editor extensions</a>: what the editor shows from your suite, in both editors.</li><li><a href="./editor-connection.html">Editor connection</a>: the instance the plugin reads, and its key.</li><li><a href="./ide-integration.html">Open in IDE</a>: open a path from the dashboard in the IDE.</li></ul>',13)])])}const f=e(i,[["render",a]]);export{p as __pageData,f as default};
